use std::sync::Mutex;
use std::thread;

fn main() {
    let data = Mutex::new(vec![1, 2, 3]);
    let mut handles = vec![];

    for i in 0..3 {
        let data = Arc::new(data.clone()); // Arc<Mutex<T>>
        handles.push(thread::spawn(move || {
            let mut lock = data.lock().unwrap(); // Блокирует поток
            lock.push(i);
        }));
    }
    for h in handles { h.join().unwrap(); }

    println!("{:?}", data.lock().unwrap());
}

